+func TestLoadOneServerScanResultLegacyListenPorts(t *testing.T) {
+	file, err := ioutil.TempFile("", "vuls-legacy-result-*.json")
+	if err != nil {
+		t.Fatal(err)
+	}
+	defer os.Remove(file.Name())
+	defer file.Close()
+
+	resultJSON := `{"packages":{"openssh":{"affectedProcs":[{"pid":"42","name":"sshd","listenPorts":["127.0.0.1:22","*:22"]}]}}}`
+	if _, err := file.WriteString(resultJSON); err != nil {
+		t.Fatal(err)
+	}
+
+	result, err := loadOneServerScanResult(file.Name())
+	if err != nil {
+		t.Fatalf("load legacy scan result: %v", err)
+	}
+	procs := result.Packages["openssh"].AffectedProcs
+	if len(procs) != 1 || !reflect.DeepEqual(procs[0].ListenPorts, []string{"127.0.0.1:22", "*:22"}) {
+		t.Fatalf("legacy listening ports were not loaded: %#v", procs)
+	}
+	if got := formatAffectedProcessPorts(procs[0]); !reflect.DeepEqual(got, procs[0].ListenPorts) {
+		t.Errorf("formatted ports = %v, want %v", got, procs[0].ListenPorts)
+	}
+}
